steps.vrml:
#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT EnvironmentalSensor : 3
COMPONENT PointingDeviceSensor : 1
COMPONENT Scripting : 1
COMPONENT Sound : 3
COMPONENT Text : 2

DEF Holder Group {
  children DEF Inl Inline {
    global TRUE
    url "content-a.wrl"
  }
}

DEF ParentClock TimeSensor {
  cycleInterval 0.5
  loop TRUE
}

DEF ParentScript Script {
  inputOnly      SFTime  tick
  initializeOnly SFInt32 n 1

  url "javascript:
    function tick (t) { n = n + 1; print ('parent tick ' + n); }
  "
}

ROUTE ParentClock.cycleTime TO ParentScript.tick

